<script setup lang="ts">
import {ref,onMounted} from 'vue';import {request,roleNames,currentUser} from './api';
const items=ref<any[]>([]),q=ref(''),page=ref(1),size=ref(25),total=ref(0),error=ref(''),busy=ref(false),opened=ref(false),editing=ref(false),action=ref(''),account=ref<any>({}),reason=ref(''),temporary=ref('');
async function load(){error.value='';try{const r=await request('/admins?'+new URLSearchParams({q:q.value,page:String(page.value),size:String(size.value)}));items.value=r.items;total.value=r.total;}catch(e){error.value=(e as Error).message;}}
function edit(row?:any){account.value=row?{...row}:{login_id:'',display_name:'',email:'',role:'VIEWER',active:true,password:''};editing.value=!!row;action.value='edit';reason.value='';temporary.value='';opened.value=true;}
function extra(row:any,kind:string){edit(row);action.value=kind;}
async function save(){error.value='';if(!reason.value.trim()){error.value='변경 이유를 입력하세요.';return;}busy.value=true;try{if(action.value==='reset')await request('/admins/'+account.value.id+'/reset-password','POST',{temporary_password:temporary.value,reason:reason.value});else if(action.value==='sessions')await request('/admins/'+account.value.id+'/end-sessions','POST',{reason:reason.value});else if(editing.value)await request('/admins/'+account.value.id,'PATCH',{display_name:account.value.display_name,email:account.value.email||null,role:account.value.role,active:account.value.active,reason:reason.value});else await request('/admins','POST',{login_id:account.value.login_id,display_name:account.value.display_name,email:account.value.email||null,role:account.value.role,password:account.value.password,reason:reason.value});opened.value=false;if(editing.value&&account.value.id===currentUser.value?.id){currentUser.value=null;}else await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script>
<template><h1>관리자 계정</h1><p class="muted">최고관리자만 계정을 관리할 수 있습니다. 권한·비밀번호·활성 상태 변경 시 기존 세션이 종료됩니다.</p><el-alert v-if="error&&!opened" :title="error" type="error" :closable="false"/><form class="toolbar" @submit.prevent="page=1;load()"><el-input v-model="q" aria-label="검색어" placeholder="로그인 ID 검색"/><el-button native-type="submit">검색</el-button><el-button type="primary" @click="edit()">관리자 생성</el-button></form><el-table :data="items"><el-table-column prop="login_id" label="로그인 ID"/><el-table-column prop="display_name" label="표시 이름"/><el-table-column label="권한"><template #default="{row}">{{roleNames[row.role as keyof typeof roleNames]}}</template></el-table-column><el-table-column label="상태"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'활성':'비활성'}}</el-tag></template></el-table-column><el-table-column label="작업" width="310"><template #default="{row}"><el-button link @click="edit(row)">편집</el-button><el-button link @click="extra(row,'reset')">비밀번호 초기화</el-button><el-button link @click="extra(row,'sessions')">세션 종료</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="size" :total="total" layout="total,prev,pager,next" @change="load"/><el-dialog v-model="opened" :title="action==='reset'?'비밀번호 초기화':action==='sessions'?'세션 종료':editing?'관리자 편집':'관리자 생성'" width="560px" destroy-on-close><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="save"><template v-if="action==='edit'"><el-form-item label="로그인 ID"><el-input aria-label="로그인 ID" v-model="account.login_id" :disabled="editing" required maxlength="100" autocomplete="off"/></el-form-item><el-form-item label="표시 이름"><el-input aria-label="표시 이름" v-model="account.display_name" required maxlength="100"/></el-form-item><el-form-item label="연락 이메일 (선택)"><el-input aria-label="연락 이메일" v-model="account.email" type="email" maxlength="254"/></el-form-item><el-form-item label="권한"><el-select aria-label="권한" v-model="account.role"><el-option v-for="(name,role) in roleNames" :key="role" :value="role" :label="name"/></el-select></el-form-item><el-checkbox v-if="editing" v-model="account.active">활성 계정</el-checkbox><el-form-item v-else label="임시 비밀번호 (15~128자)"><el-input aria-label="임시 비밀번호" v-model="account.password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required/></el-form-item></template><template v-else-if="action==='reset'"><p>{{account.login_id}} 계정에 임시 비밀번호를 설정합니다. 다음 로그인 시 변경해야 합니다.</p><el-form-item label="임시 비밀번호 (15~128자)"><el-input aria-label="임시 비밀번호" v-model="temporary" type="password" autocomplete="new-password" minlength="15" maxlength="128" required/></el-form-item></template><p v-else>{{account.login_id}} 계정의 모든 기존 세션을 종료합니다.</p><el-form-item label="변경 이유"><el-input aria-label="변경 이유" v-model="reason" type="textarea" maxlength="2000" required/></el-form-item><el-button native-type="submit" type="primary" :loading="busy">{{action==='edit'?'계정 저장':action==='reset'?'초기화 실행':'세션 종료 실행'}}</el-button><el-button @click="opened=false">취소</el-button></el-form></el-dialog></template>
